  "objects": [
    {
      "objectType": "EngineeringRule",
      "evidenceQuote": "动态加载工具会**破坏 KV Cache**——若把全部工具定义放进静态前缀，每加载一个新工具就使整段缓存失效。",
      "statement": "动态加载工具时，应把新工具的完整 schema 追加到上下文末尾，保持静态前缀稳定；不要将全部工具定义放进静态前缀。",
      "rationale": "动态加载工具会破坏 KV Cache，若把全部工具定义放进静态前缀，每加载一个新工具就使整段缓存失效。",
      "appliesWhen": "在主动工具发现场景中，需要动态加载新工具时。",
      "violation": "若修改、移除或重排已加载的工具集，缓存从变动点起失效；或将全部工具定义放进静态前缀，每加载一个新工具就使整段缓存失效。"
    },
    {
      "objectType": "AntiPattern",
